"""分析管线编排：参数校验 -> 读入 -> QC -> 归一化/HVG -> PCA -> 聚类 -> 差异表达 -> 写出。"""

from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Union

from . import __version__
from .batch import BatchSummaryRow, read_batch_metadata
